#!/usr/bin/env bash
#
# a timeout — set how long the screen stays on without input.
#
# AI DISCLOSURE: This script was entirely generated by an AI tool
set -uo pipefail
source "$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/lib/common.sh"
source "$A_LIB/device.sh"

usage() {
  cat <<USAGE
a timeout [15s|1m|5m|10m|30m|<duration>|get]

  15s        15 seconds
  1m         1 minute
  5m         5 minutes
  10m        10 minutes
  30m        30 minutes
  <duration> any number with an s or m suffix, e.g. 2m or 45s
  get        print the current timeout without changing it

Runs interactively when no argument is given.
USAGE
}

arg="${1:-}"
case "$arg" in
  -h|--help|help) usage; exit 0 ;;
esac

if [[ -z "$arg" ]]; then
  pick "Screen timeout" \
    "1m|1 minute" \
    "15s|15 seconds" \
    "5m|5 minutes" \
    "10m|10 minutes" \
    "30m|30 minutes" \
    "get|show the current timeout"
  arg="$PICK_RESULT"
fi

if [[ "$arg" == get ]]; then
  resolve_device
  banner "TIMEOUT" "a timeout get" "$DEVICE_LABEL"
  value="$("${ADB[@]}" shell settings get system screen_off_timeout | tr -d '\r')" \
    || die "failed to read screen_off_timeout"
  if [[ "$value" =~ ^[0-9]+$ ]]; then
    seconds=$((value / 1000))
    if (( seconds < 60 )); then
      pretty="${seconds}s"
    elif (( seconds % 60 == 0 )); then
      pretty="$((seconds / 60))m"
    else
      pretty="$((seconds / 60))m $((seconds % 60))s"
    fi
    printf ' screen_off_timeout  %s\n' "$pretty"
  else
    printf ' screen_off_timeout  %s\n' "$value"
  fi
  exit 0
fi

if [[ "$arg" =~ ^([0-9]+)s$ ]]; then
  millis=$((BASH_REMATCH[1] * 1000))
elif [[ "$arg" =~ ^([0-9]+)m$ ]]; then
  millis=$((BASH_REMATCH[1] * 60000))
else
  log "a timeout: unknown duration '$arg'"
  usage >&2
  exit 1
fi

resolve_device
banner "TIMEOUT" "a timeout $arg" "$DEVICE_LABEL"

"${ADB[@]}" shell settings put system screen_off_timeout "$millis" \
  || die "failed to set screen_off_timeout"

ok "screen timeout set to $arg ($millis ms)"
